export const eventNow=Date.parse('2026-10-28T20:00:00Z'),eventAt=h=>new Date(eventNow+h*3600000).toISOString();
export const eventPolygon={type:'Polygon',coordinates:[[[-101,29],[-99,29],[-99,31],[-101,31],[-101,29]]]};
export function eventFeature(){return {type:'Feature',id:'https://api.weather.gov/alerts/test',geometry:eventPolygon,properties:{id:'test',status:'Actual',messageType:'Alert',event:'High Wind Warning',sent:eventAt(-2),expires:eventAt(3),geocode:{UGC:['TXC001']},affectedZones:[]}};}
export function stationFeature(){return {type:'Feature',geometry:{type:'Point',coordinates:[-100,30]},properties:{stationIdentifier:'KAAA',name:'Test station'}};}
export function observedFeature({hour=-1,temp=20,wind=32.18688,qc='V',id='reading'}={}){return {type:'Feature',id:'https://api.weather.gov/stations/KAAA/observations/'+id,geometry:{type:'Point',coordinates:[-100,30]},properties:{station:'https://api.weather.gov/stations/KAAA',timestamp:eventAt(hour),temperature:{value:temp,unitCode:'wmoUnit:degC',qualityControl:qc},windSpeed:{value:wind,unitCode:'wmoUnit:km_h-1',qualityControl:qc},windGust:{value:null,unitCode:'wmoUnit:km_h-1',qualityControl:qc}}};}
export function observationContext(){return {scope:{windows:[{message_id:'message',revision:'alert-r',event:'High Wind Warning',start:eventAt(-2),end:eventAt(3)}]},areas:[{message_id:'message',revision:'alert-r',kind:'Alert polygon',complete:true,geometries:[{geometry:eventPolygon,revision:'alert-r',source_url:'https://api.weather.gov/alerts/test',checked_at:eventAt(0)}]}]};}
